mapper.select:
select from osh_redeem_code rc left join osh_user u on u.id = rc.user_id and u.delete_flag = 0 where rc.delete_flag = 0
and u.email = #{query.userEmail}
and rc.status = #{query.status}
and ( rc.code like concat('%', #{query.keyword}, '%') or rc.resource_no like concat('%', #{query.keyword}, '%') or rc.product_name like concat('%', #{query.keyword}, '%') or u.username like concat('%', #{query.keyword}, '%') or u.email like concat('%', #{query.keyword}, '%') )
order by rc.create_time desc, rc.id desc

select from osh_redeem_code rc left join osh_user u on u.id = rc.user_id and u.delete_flag = 0 where rc.delete_flag = 0 and rc.user_id = #{userId}
and rc.status = #{query.status}
and ( rc.code like concat('%', #{query.keyword}, '%') or rc.resource_no like concat('%', #{query.keyword}, '%') or rc.product_name like concat('%', #{query.keyword}, '%') )
order by rc.create_time desc, rc.id desc
